{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/ds_salaries.csv"
  },
  "transform": [
    {
      "aggregate": [
        {
          "op": "count",
          "field": "job_title",
          "as": "count"
        }
      ],
      "groupby": [
        "job_title"
      ]
    },
    {
      "window": [
        {
          "op": "rank",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "count",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 10"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "count",
      "type": "quantitative",
      "title": "岗位数量"
    },
    "y": {
      "field": "job_title",
      "type": "nominal",
      "title": "职位名称",
      "sort": "-x"
    }
  },
  "title": "十大最常见的数据科学职位"
}

