{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/ds_salaries.csv"
  },
  "title": "图1: 全球数据科学平均薪资热力图",
  "width": 800,
  "height": 500,
  "layer": [
    {
      "data": {
        "url": "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json",
        "format": {
          "type": "topojson",
          "feature": "countries"
        }
      },
      "mark": {
        "type": "geoshape",
        "fill": "#e0e0e0",
        "stroke": "white"
      }
    },
    {
      "transform": [
        {
          "aggregate": [{"op": "mean", "field": "salary_in_usd", "as": "avg_salary"}],
          "groupby": ["company_location"]
        },
        {
          "lookup": "company_location",
          "from": {
            "data": {
              "url": "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json",
              "format": {
                "type": "topojson",
                "feature": "countries"
              }
            },
            "key": "properties.iso_a2"
          },
          "as": "geo"
        },
        {
          "filter": "datum.geo"
        }
      ],
      "mark": {
        "type": "geoshape",
        "stroke": "white"
      },
      "encoding": {
        "shape": {"field": "geo", "type": "geojson"},
        "color": {
          "field": "avg_salary",
          "type": "quantitative",
          "scale": {"scheme": "viridis"},
          "title": "平均薪资 (USD)"
        },
        "tooltip": [
          {"field": "company_location", "type": "nominal", "title": "国家代码"},
          {"field": "avg_salary", "type": "quantitative", "title": "平均薪资", "format": "$,.0f"}
        ]
      }
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"url": "/ds_salaries.csv"},
  "title": "图2: 美国 vs. 其他地区 - 各经验级别薪资对比",
  "width": 600,
  "transform": [
    {
      "calculate": "datum.company_location == 'US' ? '美国' : '其他地区'",
      "as": "region"
    }
  ],
  "mark": "bar",
  "encoding": {
    "column": {
      "field": "experience_level",
      "type": "ordinal",
      "title": "经验水平",
      "sort": ["EN", "MI", "SE", "EX"],
      "header": {"labelAngle": 0}
    },
    "y": {
      "aggregate": "mean",
      "field": "salary_in_usd",
      "type": "quantitative",
      "title": "平均薪资 (USD)",
      "axis": {"format": "s"}
    },
    "x": {
      "field": "region",
      "type": "nominal",
      "title": "地区"
    },
    "color": {
      "field": "region",
      "type": "nominal",
      "title": "地区",
      "scale": {"range": ["#4c78a8", "#f58518"]}
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"url": "/ds_salaries.csv"},
  "title": "图3: 薪酬最高的五大职位在美国 vs. 其他地区的薪资对比",
  "transform": [
    {
      "aggregate": [{"op": "mean", "field": "salary_in_usd", "as": "global_avg_salary"}],
      "groupby": ["job_title"]
    },
    {
      "window": [{"op": "rank", "as": "rank"}],
      "sort": [{"field": "global_avg_salary", "order": "descending"}]
    },
    {"filter": "datum.rank <= 5"},
    {
      "lookup": "job_title",
      "from": {
        "data": {"url": "/ds_salaries.csv"},
        "key": "job_title",
        "fields": ["salary_in_usd", "company_location"]
      }
    },
    {
      "calculate": "datum.company_location == 'US' ? '美国' : '其他地区'",
      "as": "region"
    }
  ],
  "mark": "bar",
  "width": {"step": 50},
  "encoding": {
    "facet": {
      "field": "job_title",
      "type": "ordinal",
      "title": "全球薪酬最高的五大职位",
      "sort": {"op": "mean", "field": "salary_in_usd", "order": "descending"}
    },
    "y": {
      "aggregate": "mean",
      "field": "salary_in_usd",
      "type": "quantitative",
      "title": "平均薪资 (USD)"
    },
    "x": {
      "field": "region",
      "type": "nominal",
      "title": "地区"
    },
    "color": {
      "field": "region",
      "type": "nominal",
      "title": "地区",
      "scale": {"range": ["#4c78a8", "#f58518"]}
    },
    "tooltip": [
      {"field": "job_title", "type": "nominal", "title": "职位"},
      {"field": "region", "type": "nominal", "title": "地区"},
      {"aggregate": "mean", "field": "salary_in_usd", "type": "quantitative", "format": "$,.0f", "title": "平均薪资"}
    ]
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
