{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {"url": "/ds_salaries.csv"},
  "title": "图3: 薪酬最高的五大职位在美国 vs. 其他地区的薪资对比",
  "transform": [
    {
      "joinaggregate": [{
        "op": "mean",
        "field": "salary_in_usd",
        "as": "global_avg_salary_for_job"
      }],
      "groupby": ["job_title"]
    },
    {
      "window": [{ "op": "dense_rank", "as": "job_rank" }],
      "sort": [{ "field": "global_avg_salary_for_job", "order": "descending" }]
    },
    { "filter": "datum.job_rank <= 5" },
    {
      "calculate": "datum.company_location == 'US' ? '美国' : '其他地区'",
      "as": "region"
    }
  ],
  "mark": "bar",
  "width": {"step": 50},
  "encoding": {
    "facet": {
      "field": "job_title",
